package com.yuewei.plm.module.code.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.yuewei.plm.common.exception.BusinessException;
import com.yuewei.plm.module.operationlog.service.OperationLogCreateCommand;
import com.yuewei.plm.module.operationlog.service.OperationLogService;
import com.yuewei.plm.module.pilot.PilotAccessService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Lifecycle of the existing code/standard-phone dictionaries. Never removes a business fact. */
@Service @RequiredArgsConstructor
public class CodeLifecycleService {
 private final JdbcTemplate jdbc; private final ObjectMapper json; private final PilotAccessService access; private final OperationLogService audit;
 public record Action(@NotNull @Min(0) Long version,@NotBlank String requestId,@NotBlank @Size(max=2000) String reason) {}
 private record Identity(String table,String pk,String name,String business) {}
 private Identity identity(String kind){return switch(kind){case "code"->new Identity("plm_code_item","code_item_id","code_name","CODE_ITEM");case "phone"->new Identity("plm_phone_model_member","id","model_name","PHONE_MODEL_MEMBER");case "brand"->new Identity("plm_phone_brand","id","name","PHONE_BRAND");default->throw invalid("基础资料类型无效");};}
 public void read(){access.requireDomesticView();access.requirePhoneSelectionRead();}
 public String actorName(){return access.actor().username();}
 public void maintenance(){access.requireEngineeringMaintenance();jdbc.execute("select pg_advisory_xact_lock(66817399)");}
 public Map<String,Object> inspect(String kind,long id){read();return inspect(kind,id,row(kind,id,false,false));}
 public Map<String,Object> detail(String kind,long id){read();return row(kind,id,false,false);}
 private Map<String,Object> row(String kind,long id,boolean lock,boolean deleted){var i=identity(kind);var rows=jdbc.queryForList("select to_jsonb(t)::text value from "+i.table+" t where "+i.pk+"=?"+(deleted?"":" and deleted_flag=0")+(lock?" for update":""),id);if(rows.isEmpty())throw new BusinessException(40401,"基础资料不存在或已删除");try{return json.readValue(rows.get(0).get("value").toString(),LinkedHashMap.class);}catch(Exception failure){throw new IllegalStateException("基础资料读取失败",failure);}}

 private Map<String,Object> inspect(String kind,long id,Map<String,Object> row){
  var groups=new LinkedHashMap<String,List<Map<String,Object>>>();boolean[] hidden={false};
  references(kind,id,row).forEach(ref->{if(!Boolean.TRUE.equals(ref.remove("visible"))){hidden[0]=true;return;}groups.computeIfAbsent(Objects.toString(ref.remove("kind")),x->new ArrayList<>()).add(ref);});
  var out=new LinkedHashMap<String,Object>();out.put("id",id);out.put("name",row.get(identity(kind).name));out.put("code",Objects.toString(row.get("code_value"),""));out.put("status",row.get("status"));out.put("version",row.get("version"));out.put("canDelete",groups.isEmpty()&&!hidden[0]);out.put("canDeactivate","enabled".equals(row.get("status")));out.put("canActivate","disabled".equals(row.get("status")));out.put("hasRestrictedReferences",hidden[0]);out.put("references",groups.entrySet().stream().map(e->Map.of("kind",e.getKey(),"label",e.getKey(),"count",e.getValue().size(),"items",e.getValue())).toList());return out;
 }
 /** Exact relational IDs and typed JSON keys only; names and free-text are never identities. */
 private List<Map<String,Object>> references(String kind,long id,Map<String,Object> identityRow){
  var columns=jdbc.queryForList("select table_name,column_name,data_type from information_schema.columns where table_schema=current_schema() and left(table_name,4)='plm_' and table_name in(select table_name from information_schema.tables where table_schema=current_schema() and table_type='BASE TABLE') order by table_name,ordinal_position");
  var tables=new LinkedHashMap<String,List<String>>();var jsonColumns=new LinkedHashMap<String,List<String>>();var codeColumns=new LinkedHashMap<String,List<String>>();var compositeColumns=new LinkedHashMap<String,List<String>>();
  String codeType=Objects.toString(identityRow.get("code_type"),"");
  String originalCode=Objects.toString(identityRow.get("code_value"),"");
  Set<String> ids=kind.equals("brand")?Set.of("brand_id"):kind.equals("phone")?Set.of("phone_model_id","phone_model_member_id"):Set.of("code_item_id","phone_code_item_id","phone_model_code_item_id");
  for(var c:columns){String table=c.get("table_name").toString(),col=c.get("column_name").toString(),type=c.get("data_type").toString();if(table.equals(identity(kind).table)||table.equals("plm_operation_log")||table.equals("plm_master_data_source"))continue;
   if(ids.contains(col)&&!(("code".equals(kind)&&"code_item_id".equals(col))&&("phone_model".equals(codeType)?table.contains("color"):table.contains("phone"))))tables.computeIfAbsent(table,x->new ArrayList<>()).add(col);
   if(kind.equals("code")&&("phone_model".equals(codeType)?Set.of("phone_model_code","phone_code"):Set.of("color_code")).contains(col))codeColumns.computeIfAbsent(table,x->new ArrayList<>()).add(col);
   if(kind.equals("code")&&Set.of("mold_code","original_mold_code","product_code","finished_product_code","item_code").contains(col))compositeColumns.computeIfAbsent(table,x->new ArrayList<>()).add(col);
   if(Set.of("json","jsonb").contains(type)&&!Set.of("source_snapshot","source_data").contains(col))jsonColumns.computeIfAbsent(table,x->new ArrayList<>()).add(col);
  }
  var hits=new LinkedHashMap<String,Map<String,Object>>();
  String sourceType=switch(kind){case "code"->"code_item";case "phone"->"phone_model";default->"phone_brand";};
  if(Boolean.TRUE.equals(jdbc.queryForObject("select to_regclass(format('%I.plm_master_data_source',current_schema())) is not null",Boolean.class)))for(var r:jdbc.queryForList("select to_jsonb(s)::text value from plm_master_data_source s where (object_type=? and object_id=?) or (?='phone' and phone_model_id=?)",sourceType,id,kind,id))add(hits,"plm_master_data_source",r.get("value").toString());
  for(var e:tables.entrySet()){
   var args=new ArrayList<Object>();var predicates=new ArrayList<String>();for(String col:e.getValue()){predicates.add(col+"=?");args.add(id);}for(var r:jdbc.queryForList("select to_jsonb(t)::text value from "+e.getKey()+" t where "+String.join(" or ",predicates),args.toArray()))add(hits,e.getKey(),r.get("value").toString());
  }
  for(var e:codeColumns.entrySet()){var args=new ArrayList<Object>();var conditions=new ArrayList<String>();for(String col:e.getValue()){conditions.add("btrim("+col+"::text)=?");args.add(originalCode);}for(var r:jdbc.queryForList("select to_jsonb(t)::text value from "+e.getKey()+" t where "+String.join(" or ",conditions),args.toArray()))add(hits,e.getKey(),r.get("value").toString());}
  var generator=new com.yuewei.plm.common.util.ProductBusinessCodeGenerator();
  for(var e:compositeColumns.entrySet())for(var r:jdbc.queryForList("select to_jsonb(t)::text value from "+e.getKey()+" t where "+e.getValue().stream().map(c->c+" is not null").reduce((a,b)->a+" or "+b).orElse("false"))){try{var node=json.readTree(r.get("value").toString());boolean matched=false;for(String column:e.getValue()){String raw=node.path(column).asText("");try{if(raw.startsWith("N")){var parsed=generator.parseProductStateCode(raw);matched=originalCode.equals("phone_model".equals(codeType)?parsed.phoneModelCode():parsed.colorCode());}else if("phone_model".equals(codeType)&&raw.matches(com.yuewei.plm.common.util.ProductBusinessCodeGenerator.COMPLETE_MOLD_CODE_REGEX)){matched=originalCode.equals(generator.parseMoldCode(raw,null,List.of(),null).phoneModelCode());}}catch(BusinessException malformed){/* Unknown legacy prefixes are not evidence of a phone identity. */}if(matched)break;}if(matched)add(hits,e.getKey(),node.toString());}catch(java.io.IOException failure){throw new IllegalStateException("历史编码读取失败",failure);}}
  Set<String> keys=kind.equals("brand")?Set.of("brandId","brandIds","brand_id"):kind.equals("phone")?Set.of("phoneModelId","phoneModelIds","phoneModelMemberId","representativePhoneModelId","representativePhoneModelIds","compatiblePhoneModelIds","phone_model_id","phone_model_member_id"):"color".equals(codeType)?Set.of("colorCodeItemId","codeItemId","codeItemIds","code_item_id"):Set.of("phoneCodeItemId","phoneModelCodeItemId","codeItemId","codeItemIds","phone_code_item_id","phone_model_code_item_id","code_item_id");
  for(var e:jsonColumns.entrySet())for(var r:jdbc.queryForList("select to_jsonb(t)::text value from "+e.getKey()+" t where "+e.getValue().stream().map(c->c+" is not null").reduce((a,b)->a+" or "+b).orElse("false"))){try{var value=json.readTree(r.get("value").toString());boolean hit=false;for(String col:e.getValue())if(matches(value.get(col),keys,id,kind.equals("code")?codeType:"",originalCode)){hit=true;break;}if(hit)add(hits,e.getKey(),value.toString());}catch(Exception failure){throw new IllegalStateException("引用核对失败",failure);}}
  return new ArrayList<>(hits.values());
 }
 private boolean matches(JsonNode node,Set<String> keys,long id,String codeType,String code){if(node==null)return false;if(node.isArray()){for(var n:node)if(matches(n,keys,id,codeType,code))return true;}else if(node.isObject()){var fields=node.fields();while(fields.hasNext()){var f=fields.next();if(keys.contains(f.getKey())&&exactId(f.getValue(),id))return true;if(!codeType.isEmpty()){var codeKeys="phone_model".equals(codeType)?Set.of("phoneModelCode","phoneCode","phoneModelCodes","phone_model_code","phone_code"):Set.of("colorCode","colorCodes","color_code");if(codeKeys.contains(f.getKey())&&exactCode(f.getValue(),code))return true;if(Set.of("moldCode","originalMoldCode","productCode","finishedProductCode","itemCode","mold_code","original_mold_code","finished_product_code").contains(f.getKey())&&compositeCode(f.getValue(),codeType,code))return true;}if(matches(f.getValue(),keys,id,codeType,code))return true;}}return false;}
 private boolean exactCode(JsonNode node,String code){if(node.isArray()){for(var value:node)if(exactCode(value,code))return true;return false;}return node.isTextual()&&node.asText().strip().equals(code);}
 private boolean compositeCode(JsonNode node,String type,String code){if(!node.isTextual())return false;String raw=node.asText();var generator=new com.yuewei.plm.common.util.ProductBusinessCodeGenerator();try{if(raw.startsWith("N")){var value=generator.parseProductStateCode(raw);return code.equals("phone_model".equals(type)?value.phoneModelCode():value.colorCode());}if("phone_model".equals(type)&&raw.matches(com.yuewei.plm.common.util.ProductBusinessCodeGenerator.COMPLETE_MOLD_CODE_REGEX))return code.equals(generator.parseMoldCode(raw,null,List.of(),null).phoneModelCode());}catch(BusinessException malformed){return false;}return false;}

 private boolean exactId(JsonNode node,long id){if(node.isArray()){for(var n:node)if(exactId(n,id))return true;return false;}return node.isIntegralNumber()?node.longValue()==id:node.isTextual()&&String.valueOf(id).equals(node.asText());}
 private void add(Map<String,Map<String,Object>> out,String table,String value){try{var node=json.readTree(value);String pk="";for(String key:List.of("product_id","item_id","mold_set_id","product_bom_id","process_id","application_id","attachment_id","id"))if(node.hasNonNull(key)){pk=key+":"+node.get(key).asText();break;}if(pk.isEmpty()&&node.hasNonNull("source_key"))pk="source:"+node.get("source_key").asText();if(pk.isEmpty())pk="历史行";String key=table+":"+java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));String label=label(table)+" · "+pk;for(String field:List.of("product_name","mold_name","model_name","name","title","application_no","product_code"))if(node.hasNonNull(field)&&!node.get(field).asText().isBlank()){label=node.get(field).asText()+" · "+pk;break;}var row=new LinkedHashMap<String,Object>();row.put("kind",label(table));row.put("id",key);row.put("label",label);boolean historical=node.path("deleted_flag").asInt()==1;row.put("history",historical);row.put("visible",visible(table,node));if(!historical){if(node.hasNonNull("product_id"))row.put("targetPath","/projects?projectId="+node.get("product_id").asLong());else if(node.hasNonNull("item_id"))row.put("targetPath","/molds?itemId="+node.get("item_id").asLong());}out.putIfAbsent(key,row);}catch(Exception failure){throw new IllegalStateException("引用资料解析失败",failure);}}
 private boolean visible(String table,JsonNode row){if(table.contains("cost")||table.contains("expense")||table.contains("finance")){if(!access.hasPermission("finance:read"))return false;}else if(table.contains("attachment")||table.contains("document")){if(!access.hasPermission("file:read"))return false;}else if(!access.hasPermission("collaboration:view")&&!access.hasPermission("product:view"))return false;if(access.access().allObjects())return true;try{if(row.hasNonNull("product_id")){access.requireProduct(row.get("product_id").asLong());return true;}if(row.hasNonNull("item_id")){access.requireItem(row.get("item_id").asLong());return true;}if(row.hasNonNull("attachment_id")){access.requireFile(row.get("attachment_id").asLong());return true;}}catch(BusinessException denied){return false;}return false;}
 private String label(String table){if(table.equals("plm_master_data_source"))return "CRM／MES来源映射";if(table.contains("phone_model"))return "标准手机成员";if(table.contains("phone_code_brand"))return "手机编码品牌";if(table.contains("mold_application"))return "开模申请";if(table.contains("collaboration"))return "模具与排程";if(table.contains("bom"))return "BOM与工艺";if(table.contains("product"))return "产品与型号";if(table.contains("attachment")||table.contains("document"))return "图纸与附件";if(table.contains("market"))return "新品监控";return "业务记录（"+table.substring(4)+"）";}
 @Transactional public Map<String,Object> act(String kind,long id,String action,Action input,HttpServletRequest request){
  maintenance();var actor=access.actor();var i=identity(kind);if(!Set.of("delete","deactivate","activate").contains(action))throw invalid("基础资料操作无效");if(input==null||input.version()==null||input.version()<0||input.reason()==null||input.reason().isBlank()||input.reason().strip().length()>2000)throw invalid("请填写操作原因与当前版本");try{if(!UUID.fromString(input.requestId()).toString().equals(input.requestId()))throw new IllegalArgumentException();}catch(Exception e){throw invalid("操作请求标识无效");}
  var before=row(kind,id,true,true);var payload=new TreeMap<String,Object>();payload.put("action",action);payload.put("version",input.version());payload.put("reason",input.reason().strip());String payloadHash=payloadHash(payload);
  for(var log:jdbc.queryForList("select detail_json from plm_operation_log where business_type=? and business_id=? and operator_user_id=? order by log_id desc",i.business,String.valueOf(id),actor.userId())){try{var detail=json.readTree(Objects.toString(log.get("detail_json"),"{}"));if(input.requestId().equals(detail.path("requestId").asText())){if(!(detail.hasNonNull("payloadHash")?payloadHash.equals(detail.path("payloadHash").asText()):json.readTree(json.writeValueAsString(payload)).equals(detail.get("payload"))))throw new BusinessException(40901,"同一请求标识不能用于不同操作");var result=json.convertValue(detail.get("result"),LinkedHashMap.class);result.put("id",((Number)result.get("id")).longValue());result.put("version",((Number)result.get("version")).longValue());return result;}}catch(com.fasterxml.jackson.core.JsonProcessingException ignored){/* Older free-form audit entries do not carry an idempotency contract. */}}
  if(((Number)before.get("deleted_flag")).intValue()!=0)throw new BusinessException(40401,"基础资料已删除");if(((Number)before.get("version")).longValue()!=input.version())throw new BusinessException(40901,"资料已被修改，请刷新后重新确认");
  var inspected=inspect(kind,id,before);if(action.equals("delete")&&!Boolean.TRUE.equals(inspected.get("canDelete")))throw new BusinessException(40901,"存在业务或历史引用，不能删除；可停用并保留记录");
  String status=action.equals("activate")?"enabled":"disabled";if(action.equals("activate")&&kind.equals("phone")){var r=jdbc.queryForList("select b.status,b.deleted_flag from plm_phone_brand b where b.id=? for share",before.get("brand_id"));if(r.isEmpty()||!"enabled".equals(r.get(0).get("status"))||((Number)r.get(0).get("deleted_flag")).intValue()!=0)throw invalid("所属品牌已停用或删除，请先维护品牌");}
  jdbc.update("update "+i.table+" set status=?,deleted_flag=?,version=version+1,updated_at=now(),updated_by=? where "+i.pk+"=?",status,action.equals("delete")?1:0,actor.username(),id);
  var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("status",action.equals("delete")?"deleted":status);result.put("version",input.version()+1);
  var details=new LinkedHashMap<String,Object>();details.put("before",before);details.put("after",row(kind,id,false,true));details.put("requestId",input.requestId());details.put("payload",payload);details.put("payloadHash",payloadHash);details.put("result",result);
  audit.logRequired(OperationLogCreateCommand.builder().action(action.toUpperCase(Locale.ROOT)).businessType(i.business).businessId(String.valueOf(id)).businessName(Objects.toString(before.get(i.name))).detailJson(json.valueToTree(details).toString()).request(request).build(),actor);return result;
 }
 public void saved(long id,Object before,Object after,String reason){var actor=access.requireEngineeringMaintenance();var details=new LinkedHashMap<String,Object>();details.put("before",before);details.put("after",after);details.put("reason",reason);var attributes=org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();var request=attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servlet?servlet.getRequest():null;audit.logRequired(OperationLogCreateCommand.builder().action(before==null?"CREATE":"UPDATE").businessType("CODE_ITEM").businessId(String.valueOf(id)).businessName("基础编码维护").detailJson(json.valueToTree(details).toString()).request(request).build(),actor);}
 private String payloadHash(Map<String,Object> payload){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(payload)));}catch(Exception failure){throw new IllegalStateException("请求摘要失败",failure);}}
 private static BusinessException invalid(String m){return new BusinessException(40001,m);}
}
